module spell_power_calculator(input clk, input rst_n, input start, input [7:0] char_in, input [3:0] char_index, input valid_input, output reg [7:0] power, output reg done); reg [2:0] state_reg; reg [7:0] mem [15:0]; reg [15:0] count; reg all_received; reg [7:0] max_power_reg; reg [7:0] power_reg; reg done_reg; reg [2:0] next_state; wire [7:0] max_power; // L=4 condition assign has_L4 = (mem[4]==mem[3] && mem[5]==mem[2] && mem[6]==mem[1] && mem[7]==mem[0] && mem[8]==mem[0] && mem[9]==mem[1] && mem[10]==mem[2] && mem[11]==mem[3] && mem[12]==mem[3] && mem[13]==mem[2] && mem[14]==mem[1] && mem[15]==mem[0]); // L=3 conditions wire [4:0] cond_L3; assign cond_L3[0] = (mem[3]==mem[2] && mem[4]==mem[1] && mem[5]==mem[0] && mem[6]==mem[0] && mem[7]==mem[1] && mem[8]==mem[2] && mem[9]==mem[2] && mem[10]==mem[1] && mem[11]==mem[0]); assign cond_L3[1] = (mem[4]==mem[3] && mem[5]==mem[2] && mem[6]==mem[1] && mem[7]==mem[1] && mem[8]==mem[2] && mem[9]==mem[0] && mem[10]==mem[2] && mem[11]==mem[1] && mem[12]==mem[0]); assign cond_L3[2] = (mem[5]==mem[4] && mem[6]==mem[3] && mem[7]==mem[2] && mem[8]==mem[2] && mem[9]==mem[3] && mem[10]==mem[4] && mem[11]==mem[4] && mem[12]==mem[3] && mem[13]==mem[2]); assign cond_L3[3] = (mem[6]==mem[5] && mem[7]==mem[4] && mem[8]==mem[3] && mem[9]==mem[3] && mem[10]==mem[4] && mem[11]==mem[5] && mem[12]==mem[5] && mem[13]==mem[4] && mem[14]==mem[3]); assign cond_L3[4] = (mem[7]==mem[6] && mem[8]==mem[5] && mem[9]==mem[4] && mem[10]==mem[4] && mem[11]==mem[5] && mem[12]==mem[6] && mem[13]==mem[6] && mem[14]==mem[5] && mem[15]==mem[4]); wire has_L3; assign has_L3 = cond_L3[0] || cond_L3[1] || cond_L3[2] || cond_L3[3] || cond_L3[4]; // L=2 conditions wire [8:0] cond_L2; assign cond_L2[0] = (mem[2]==mem[1] && mem[3]==mem[0] && mem[4]==mem[0] && mem[5]==mem[1] && mem[6]==mem[1] && mem[7]==mem[0]); assign cond_L2[1] = (mem[3]==mem[2] && mem[4]==mem[1] && mem[5]==mem[1] && mem[6]==mem[2] && mem[7]==mem[1] && mem[8]==mem[0]); assign cond_L2[2] = (mem[4]==mem[3] && mem[5]==mem[2] && mem[6]==mem[2] && mem[7]==mem[3] && mem[8]==mem[2] && mem[9]==mem[3]); assign cond_L2[3] = (mem[5]==mem[4] && mem[6]==mem[3] && mem[7]==mem[3] && mem[8]==mem[4] && mem[9]==mem[3] && mem[10]==mem[4]); assign cond_L2[4] = (mem[6]==mem[5] && mem[7]==mem[4] && mem[8]==mem[4] && mem[9]==mem[5] && mem[10]==mem[4] && mem[11]==mem[5]); assign cond_L2[5] = (mem[7]==mem[6] && mem[8]==mem[5] && mem[9]==mem[5] && mem[10]==mem[6] && mem[11]==mem[5] && mem[12]==mem[6]); assign cond_L2[6] = (mem[8]==mem[7] && mem[9]==mem[6] && mem[10]==mem[6] && mem[11]==mem[7] && mem[12]==mem[6] && mem[13]==mem[7]); assign cond_L2[7] = (mem[9]==mem[8] && mem[10]==mem[7] && mem[11]==mem[7] && mem[12]==mem[8] && mem[13]==mem[7] && mem[14]==mem[8]); assign cond_L2[8] = (mem[10]==mem[9] && mem[11]==mem[8] && mem[12]==mem[8] && mem[13]==mem[9] && mem[14]==mem[9] && mem[15]==mem[8]); wire has_L2; assign has_L2 = cond_L2[0] || cond_L2[1] || cond_L2[2] || cond_L2[3] || cond_L2[4] || cond_L2[5] || cond_L2[6] || cond_L2[7] || cond_L2[8]; // L=1 conditions wire [12:0] cond_L1; assign cond_L1[0] = (mem[0]==mem[1] && mem[0]==mem[2] && mem[0]==mem[3]); assign cond_L1[1] = (mem[1]==mem[2] && mem[1]==mem[3] && mem[1]==mem[4]); assign cond_L1[2] = (mem[2]==mem[3] && mem[2]==mem[4] && mem[2]==mem[5]); assign cond_L1[3] = (mem[3]==mem[4] && mem[3]==mem[5] && mem[3]==mem[6]); assign cond_L1[4] = (mem[4]==mem[5] && mem[4]==mem[6] && mem[4]==mem[7]); assign cond_L1[5] = (mem[5]==mem[6] && mem[5]==mem[7] && mem[5]==mem[8]); assign cond_L1[6] = (mem[6]==mem[7] && mem[6]==mem[8] && mem[6]==mem[9]); assign cond_L1[7] = (mem[7]==mem[8] && mem[7]==mem[9] && mem[7]==mem[10]); assign cond_L1[8] = (mem[8]==mem[9] && mem[8]==mem[10] && mem[8]==mem[11]); assign cond_L1[9] = (mem[9]==mem[10] && mem[9]==mem[11] && mem[9]==mem[12]); assign cond_L1[10] = (mem[10]==mem[11] && mem[10]==mem[12] && mem[10]==mem[13]); assign cond_L1[11] = (mem[11]==mem[12] && mem[11]==mem[13] && mem[11]==mem[14]); assign cond_L1[12] = (mem[12]==mem[13] && mem[12]==mem[14] && mem[12]==mem[15]); wire has_L1; assign has_L1 = cond_L1[0] || cond_L1[1] || cond_L1[2] || cond_L1[3] || cond_L1[4] || cond_L1[5] || cond_L1[6] || cond_L1[7] || cond_L1[8] || cond_L1[9] || cond_L1[10] || cond_L1[11] || cond_L1[12]; // Compute max_power assign max_power = (has_L4 ? 16 : (has_L3 ? 12 : (has_L2 ? 8 : (has_L1 ? 4 : 0)))); // State machine always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state_reg <= 3'd0; mem <= 16'b0; count <= 16'b0; all_received <= 1'b0; max_power_reg <= 8'b0; power_reg <= 8'b0; done_reg <= 1'b0; end else begin state_reg <= next_state; case (state_reg) 3'd0: // IDLE if (valid_input) begin next_state = 3'd1; mem[char_index] = char_in; count = count + 1; all_received = (count == 16) ? 1'b1 : 1'b0; end else begin next_state = 3'd0; end 3'd1: // COLLECTING if (valid_input) begin mem[char_index] = char_in; count = count + 1; all_received = (count == 16) ? 1'b1 : 1'b0; next_state = 3'd1; end if (start && all_received) begin next_state = 3'd2; end 3'd2: // CHECKING next_state = 3'd3; max_power_reg <= max_power; 3'd3: // DONE next_state = 3'd3; power_reg <= max_power_reg; done_reg <= 1'b1; default: next_state = 3'd0; endcase endcase // Update outputs power_reg <= max_power_reg; done_reg <= done_reg; end endmodule